import { useState, memo, useMemo, useCallback } from 'react';

const items = [
  { id: 1, name: 'Learn JSX', xp: 75 },
  { id: 2, name: 'Master Hooks', xp: 150 },
  { id: 3, name: 'Build a custom hook', xp: 200 },
];

// TODO: wrap in memo
function ExpensiveList({ items, onItemClick }) {
  return (
    <ul>
      {items.map(item => (
        <li key={item.id} onClick={() => onItemClick(item.id)}>
          {item.name} ({item.xp} XP)
        </li>
      ))}
    </ul>
  );
}

export default function App() {
  const [count, setCount] = useState(0);

  // TODO: stabilise with useCallback
  const handleItemClick = (id) => console.log('Clicked item', id);

  // TODO: cache with useMemo
  const totalXP = items.reduce((sum, item) => sum + item.xp, 0);

  return (
    <div>
      <button onClick={() => setCount(c => c + 1)}>Count: {count}</button>
      <p data-testid="total">Total XP: {totalXP}</p>
      <ExpensiveList items={items} onItemClick={handleItemClick} />
    </div>
  );
}
